/*
 * permutations.c -- permutations in cycle notation and permutation groups.
 *
 *   Cycles[{{c1, c2, ...}, ...}]      canonical cycle form (a value: Cycles
 *                                     evaluates only to put itself in order)
 *   PermutationGroup[{g1, g2, ...}]   the group generated by the Cycles gi
 *                                     (inert: the generators are the group)
 *   PermutationList[perm (, n)]       the image list {perm(1), ..., perm(n)}
 *   PermutationCycles[list]           the Cycles of a permutation list
 *   GroupElements[group (, {k...})]   every element, ordered by image list
 *   GroupOrder[group]                 the number of elements
 *
 * Permute[expr, group] (funcprog.c) is the list of expr permuted by every
 * element and reaches the group through perm_group_elements().
 *
 * A permutation of degree n is held as its 0-based image array p[0..n-1]
 * (point i+1 goes to p[i]+1).  Group elements are enumerated by closing the
 * generator set under composition (breadth-first, each new element times
 * every generator), with an open-addressing hash set over the image arrays.
 * That is O(|G| * #gens * n) time and O(|G| * n) memory: exactly what
 * GroupElements has to produce anyway.  GroupOrder uses the same closure, so
 * it too is limited to groups whose elements fit in memory (a Schreier-Sims
 * order would lift that); past PERM_MAX_ELEMENTS the call is left
 * unevaluated rather than exhausting memory.
 */
#include "permutations.h"
#include "expr.h"
#include "symtab.h"
#include "attr.h"
#include "sym_names.h"
#include "message.h"
#include "print.h"
#include <stdint.h>
#include <stdlib.h>
#include <string.h>

/* Elements x degree beyond which an enumeration declines (about 512 MB). */
#define PERM_MAX_CELLS (UINT64_C(1) << 27)

static bool is_list(const Expr* e) {
    return e && e->type == EXPR_FUNCTION && e->data.function.head->type == EXPR_SYMBOL &&
           e->data.function.head->data.symbol.name == SYM_List;
}

static bool has_head(const Expr* e, const char* sym) {
    return e && e->type == EXPR_FUNCTION && e->data.function.head->type == EXPR_SYMBOL &&
           e->data.function.head->data.symbol.name == sym;
}

static void msg_expr(const char* head, const char* tag, const char* fmt, const Expr* e) {
    char* t = expr_to_string_outputform((Expr*)e);
    mth_message(head, tag, fmt, t ? t : "");
    free(t);
}

/* ------------------------------------------------------------------ */
/* Cycles                                                              */
/* ------------------------------------------------------------------ */

/* Validate Cycles[cl]'s argument.  Returns 1 when every point is a positive
 * integer, all distinct (writing the largest to *maxpt); 0 when it is not
 * concrete (a symbolic point: the Cycles stays as written, no message); -1
 * after a message for a malformed one.  `whole` is the Cycles expression,
 * for the message. */
static int cycles_check(const Expr* cl, const Expr* whole, int64_t* maxpt) {
    *maxpt = 0;
    if (!is_list(cl)) goto intpoint;
    for (size_t c = 0; c < cl->data.function.arg_count; c++) {
        const Expr* cyc = cl->data.function.args[c];
        if (!is_list(cyc)) goto intpoint;
        for (size_t j = 0; j < cyc->data.function.arg_count; j++) {
            const Expr* p = cyc->data.function.args[j];
            if (p->type == EXPR_INTEGER) {
                if (p->data.integer <= 0) {
                    msg_expr("Cycles", "pospoint", "%s contains integers that are not positive.", whole);
                    return -1;
                }
                if (p->data.integer > *maxpt) *maxpt = p->data.integer;
            } else if (p->type == EXPR_REAL || p->type == EXPR_BIGINT ||
                       has_head(p, SYM_Rational) || has_head(p, SYM_Complex)) {
                goto intpoint;
            } else {
                return 0;
            }
        }
    }
    if ((uint64_t)*maxpt > PERM_MAX_CELLS) return 0;
    {
        unsigned char* seen = calloc((size_t)*maxpt + 1, 1);
        if (!seen) return 0;
        for (size_t c = 0; c < cl->data.function.arg_count; c++) {
            const Expr* cyc = cl->data.function.args[c];
            for (size_t j = 0; j < cyc->data.function.arg_count; j++) {
                int64_t v = cyc->data.function.args[j]->data.integer;
                if (seen[v]) {
                    free(seen);
                    msg_expr("Cycles", "reppoint", "%s contains repeated integers.", whole);
                    return -1;
                }
                seen[v] = 1;
            }
        }
        free(seen);
    }
    return 1;
intpoint:
    msg_expr("Cycles", "intpoint", "%s is expected to contain a list of lists of integers.", whole);
    return -1;
}

/* Images (0-based, length n) of a validated Cycles argument cl. */
static void cycles_images(const Expr* cl, uint32_t* img, size_t n) {
    for (size_t i = 0; i < n; i++) img[i] = (uint32_t)i;
    for (size_t c = 0; c < cl->data.function.arg_count; c++) {
        const Expr* cyc = cl->data.function.args[c];
        size_t m = cyc->data.function.arg_count;
        for (size_t j = 0; j < m; j++)
            img[cyc->data.function.args[j]->data.integer - 1] =
                (uint32_t)(cyc->data.function.args[(j + 1) % m]->data.integer - 1);
    }
}

/* The canonical Cycles of an image array: each cycle starts at its smallest
 * point, fixed points are dropped, cycles are ordered by their first point
 * (which a scan from point 1 produces directly). */
static Expr* images_to_cycles(const uint32_t* img, size_t n) {
    unsigned char* seen = calloc(n ? n : 1, 1);
    Expr** cyc = malloc(sizeof(Expr*) * (n ? n : 1));
    size_t nc = 0;
    Expr** pts = malloc(sizeof(Expr*) * (n ? n : 1));
    for (size_t i = 0; i < n; i++) {
        if (seen[i] || img[i] == i) { seen[i] = 1; continue; }
        size_t m = 0;
        for (size_t j = i; !seen[j]; j = img[j]) {
            seen[j] = 1;
            pts[m++] = expr_new_integer((int64_t)j + 1);
        }
        cyc[nc++] = expr_new_function(expr_new_symbol(SYM_List), pts, m);
    }
    free(pts);
    free(seen);
    Expr* l = expr_new_function(expr_new_symbol(SYM_List), cyc, nc);
    free(cyc);
    return expr_new_function(expr_new_symbol(SYM_Cycles), &l, 1);
}

/* Cycles[{{3, 1, 2}, {5, 4}}] -> Cycles[{{1, 2, 3}, {4, 5}}];
 * Cycles[{{1}}] -> Cycles[{}].  Unevaluated when already canonical, or when
 * a point is symbolic. */
static Expr* builtin_cycles(Expr* res) {
    if (res->type != EXPR_FUNCTION || res->data.function.arg_count != 1) return NULL;
    const Expr* cl = res->data.function.args[0];
    int64_t maxpt;
    if (cycles_check(cl, res, &maxpt) != 1) return NULL;
    size_t n = (size_t)maxpt;
    uint32_t* img = malloc(sizeof(uint32_t) * (n ? n : 1));
    cycles_images(cl, img, n);
    Expr* canon = images_to_cycles(img, n);
    free(img);
    if (expr_eq(canon, res)) {
        expr_free(canon);
        return NULL;
    }
    return canon;
}

/* ------------------------------------------------------------------ */
/* Permutation lists                                                   */
/* ------------------------------------------------------------------ */

/* A permutation list {p1, ..., pk} as images; NULL (after a `head`::permlist
 * message unless quiet) when invalid.  *k gets the length. */
static uint32_t* list_images(const Expr* l, size_t* k, const char* head, bool quiet) {
    if (!is_list(l)) return NULL;
    size_t n = l->data.function.arg_count;
    uint32_t* img = malloc(sizeof(uint32_t) * (n ? n : 1));
    unsigned char* seen = calloc(n ? n : 1, 1);
    bool ok = true;
    for (size_t i = 0; i < n && ok; i++) {
        const Expr* p = l->data.function.args[i];
        ok = p->type == EXPR_INTEGER && p->data.integer >= 1 && (uint64_t)p->data.integer <= n &&
             !seen[p->data.integer - 1];
        if (ok) {
            seen[p->data.integer - 1] = 1;
            img[i] = (uint32_t)(p->data.integer - 1);
        }
    }
    free(seen);
    if (!ok) {
        free(img);
        if (!quiet) msg_expr(head, "permlist", "Invalid permutation list %s.", l);
        return NULL;
    }
    *k = n;
    return img;
}

static Expr* images_to_list(const uint32_t* img, size_t n) {
    Expr** a = malloc(sizeof(Expr*) * (n ? n : 1));
    for (size_t i = 0; i < n; i++) a[i] = expr_new_integer((int64_t)img[i] + 1);
    Expr* l = expr_new_function(expr_new_symbol(SYM_List), a, n);
    free(a);
    return l;
}

/* The images of a canonical-or-not concrete Cycles, at its own degree (its
 * largest point).  NULL when perm is not a concrete Cycles. */
static uint32_t* cycles_expr_images(const Expr* perm, size_t* n) {
    if (!has_head(perm, SYM_Cycles) || perm->data.function.arg_count != 1) return NULL;
    int64_t maxpt;
    if (cycles_check(perm->data.function.args[0], perm, &maxpt) != 1) return NULL;
    *n = (size_t)maxpt;
    uint32_t* img = malloc(sizeof(uint32_t) * (*n ? *n : 1));
    cycles_images(perm->data.function.args[0], img, *n);
    return img;
}

/* PermutationList[Cycles[...]] -> {perm(1), ..., perm(m)} up to the largest
 * moved point m; PermutationList[perm, n] pads to length n
 * (PermutationList::lowlen when n is below the largest moved point).  A
 * permutation list is returned as is (padded to n). */
static Expr* builtin_permutationlist(Expr* res) {
    if (res->type != EXPR_FUNCTION) return NULL;
    size_t argc = res->data.function.arg_count;
    if (argc != 1 && argc != 2) return NULL;
    const Expr* perm = res->data.function.args[0];
    int64_t want = -1;
    if (argc == 2) {
        const Expr* ne = res->data.function.args[1];
        if (ne->type != EXPR_INTEGER || ne->data.integer < 0) return NULL;
        want = ne->data.integer;
    }
    size_t n = 0;
    uint32_t* img = is_list(perm) ? list_images(perm, &n, "PermutationList", false)
                                  : cycles_expr_images(perm, &n);
    if (!img) return NULL;
    /* The support ends at the largest moved point. */
    size_t supp = n;
    while (supp > 0 && img[supp - 1] == supp - 1) supp--;
    if (want >= 0 && (size_t)want < supp) {
        char* t = expr_to_string_outputform((Expr*)perm);
        mth_message("PermutationList", "lowlen",
                    "Required length %lld is smaller than maximum %lld of support of %s.",
                    (long long)want, (long long)supp, t ? t : "");
        free(t);
        free(img);
        return NULL;
    }
    size_t len = want >= 0 ? (size_t)want : (is_list(perm) ? n : supp);
    uint32_t* out = malloc(sizeof(uint32_t) * (len ? len : 1));
    for (size_t i = 0; i < len; i++) out[i] = i < n ? img[i] : (uint32_t)i;
    free(img);
    Expr* r = images_to_list(out, len);
    free(out);
    return r;
}

/* PermutationCycles[{2, 3, 1}] -> Cycles[{{1, 2, 3}}]. */
static Expr* builtin_permutationcycles(Expr* res) {
    if (res->type != EXPR_FUNCTION || res->data.function.arg_count != 1) return NULL;
    size_t n = 0;
    uint32_t* img = list_images(res->data.function.args[0], &n, "PermutationCycles", false);
    if (!img) return NULL;
    Expr* r = images_to_cycles(img, n);
    free(img);
    return r;
}

/* ------------------------------------------------------------------ */
/* Permutation groups                                                  */
/* ------------------------------------------------------------------ */

/* Open-addressing set of image arrays of one degree. */
typedef struct {
    uint32_t* cells;   /* count * deg images, insertion order */
    size_t count, cap_elems;
    size_t* slots;     /* index + 1, 0 = empty */
    size_t nslots;
    size_t deg;
} PermSet;

static uint64_t perm_hash(const uint32_t* p, size_t n) {
    uint64_t h = UINT64_C(1469598103934665603);
    for (size_t i = 0; i < n; i++) {
        h ^= p[i];
        h *= UINT64_C(1099511628211);
    }
    return h;
}

/* Insert p; returns 1 if new, 0 if present, -1 on memory exhaustion. */
static int permset_add(PermSet* s, const uint32_t* p) {
    if (2 * (s->count + 1) > s->nslots) {
        size_t ns = s->nslots ? 2 * s->nslots : 64;
        size_t* nsl = calloc(ns, sizeof(size_t));
        if (!nsl) return -1;
        for (size_t i = 0; i < s->count; i++) {
            size_t h = (size_t)(perm_hash(s->cells + i * s->deg, s->deg) & (ns - 1));
            while (nsl[h]) h = (h + 1) & (ns - 1);
            nsl[h] = i + 1;
        }
        free(s->slots);
        s->slots = nsl;
        s->nslots = ns;
    }
    size_t h = (size_t)(perm_hash(p, s->deg) & (s->nslots - 1));
    while (s->slots[h]) {
        if (memcmp(s->cells + (s->slots[h] - 1) * s->deg, p, s->deg * sizeof(uint32_t)) == 0)
            return 0;
        h = (h + 1) & (s->nslots - 1);
    }
    if (s->count == s->cap_elems) {
        size_t nc = s->cap_elems ? 2 * s->cap_elems : 64;
        uint32_t* g = realloc(s->cells, nc * (s->deg ? s->deg : 1) * sizeof(uint32_t));
        if (!g) return -1;
        s->cells = g;
        s->cap_elems = nc;
    }
    memcpy(s->cells + s->count * s->deg, p, s->deg * sizeof(uint32_t));
    s->slots[h] = ++s->count;
    return 1;
}

static size_t g_sort_deg;
static int perm_cmp(const void* a, const void* b) {
    const uint32_t* x = a;
    const uint32_t* y = b;
    for (size_t i = 0; i < g_sort_deg; i++)
        if (x[i] != y[i]) return x[i] < y[i] ? -1 : 1;
    return 0;
}

uint32_t* perm_group_elements(const Expr* group, size_t* order, size_t* deg) {
    if (!has_head(group, SYM_PermutationGroup) || group->data.function.arg_count != 1) return NULL;
    const Expr* gl = group->data.function.args[0];
    if (!is_list(gl)) return NULL;
    size_t ng = gl->data.function.arg_count;
    /* Degree: the largest point any generator moves. */
    size_t n = 0;
    uint32_t** gens = calloc(ng ? ng : 1, sizeof(uint32_t*));
    size_t* gdeg = calloc(ng ? ng : 1, sizeof(size_t));
    bool ok = true;
    for (size_t i = 0; i < ng && ok; i++) {
        gens[i] = cycles_expr_images(gl->data.function.args[i], &gdeg[i]);
        ok = gens[i] != NULL;
        if (ok && gdeg[i] > n) n = gdeg[i];
    }
    PermSet s = { NULL, 0, 0, NULL, 0, n };
    uint32_t* result = NULL;
    uint32_t* id = NULL;
    uint32_t* gfull = NULL;
    uint32_t* prod = NULL;
    if (!ok) goto done;
    id = malloc(sizeof(uint32_t) * (n ? n : 1));
    gfull = malloc(sizeof(uint32_t) * (n ? n : 1) * (ng ? ng : 1));
    prod = malloc(sizeof(uint32_t) * (n ? n : 1));
    for (size_t i = 0; i < n; i++) id[i] = (uint32_t)i;
    /* Generators widened to the group degree. */
    for (size_t g = 0; g < ng; g++)
        for (size_t i = 0; i < n; i++)
            gfull[g * n + i] = i < gdeg[g] ? gens[g][i] : (uint32_t)i;
    if (permset_add(&s, id) < 0) goto done;
    /* Breadth-first closure: element e times generator g (apply g, then e). */
    for (size_t k = 0; k < s.count; k++) {
        for (size_t g = 0; g < ng; g++) {
            const uint32_t* e = s.cells + k * n;
            const uint32_t* gg = gfull + g * n;
            for (size_t i = 0; i < n; i++) prod[i] = e[gg[i]];
            int r = permset_add(&s, prod);
            if (r < 0) goto done;
            if ((uint64_t)s.count * (n ? n : 1) > PERM_MAX_CELLS) goto done;
        }
    }
    g_sort_deg = n;
    if (n) qsort(s.cells, s.count, n * sizeof(uint32_t), perm_cmp);
    result = s.cells;
    s.cells = NULL;
    *order = s.count;
    *deg = n;
done:
    for (size_t i = 0; i < ng; i++) free(gens[i]);
    free(gens);
    free(gdeg);
    free(id);
    free(gfull);
    free(prod);
    free(s.cells);
    free(s.slots);
    return result;
}

/* GroupElements[group] -> every element as a Cycles, ordered by image list;
 * GroupElements[group, {k1, ...}] -> the elements at those positions
 * (negative counts from the end). */
static Expr* builtin_groupelements(Expr* res) {
    if (res->type != EXPR_FUNCTION) return NULL;
    size_t argc = res->data.function.arg_count;
    if (argc != 1 && argc != 2) return NULL;
    const Expr* sel = argc == 2 ? res->data.function.args[1] : NULL;
    if (sel && !is_list(sel)) return NULL;
    if (sel)
        for (size_t i = 0; i < sel->data.function.arg_count; i++)
            if (sel->data.function.args[i]->type != EXPR_INTEGER) return NULL;
    size_t order = 0, n = 0;
    uint32_t* el = perm_group_elements(res->data.function.args[0], &order, &n);
    if (!el) return NULL;
    size_t m = sel ? sel->data.function.arg_count : order;
    Expr** out = malloc(sizeof(Expr*) * (m ? m : 1));
    for (size_t i = 0; i < m; i++) {
        size_t k = i;
        if (sel) {
            int64_t v = sel->data.function.args[i]->data.integer;
            int64_t idx = v > 0 ? v - 1 : (int64_t)order + v;
            if (v == 0 || idx < 0 || idx >= (int64_t)order) {
                for (size_t j = 0; j < i; j++) expr_free(out[j]);
                free(out);
                free(el);
                return NULL;
            }
            k = (size_t)idx;
        }
        out[i] = images_to_cycles(el + k * n, n);
    }
    free(el);
    Expr* r = expr_new_function(expr_new_symbol(SYM_List), out, m);
    free(out);
    return r;
}

/* GroupOrder[group] -> the number of elements. */
static Expr* builtin_grouporder(Expr* res) {
    if (res->type != EXPR_FUNCTION || res->data.function.arg_count != 1) return NULL;
    size_t order = 0, n = 0;
    uint32_t* el = perm_group_elements(res->data.function.args[0], &order, &n);
    if (!el) return NULL;
    free(el);
    return expr_new_integer((int64_t)order);
}

void permutations_init(void) {
    symtab_add_builtin("Cycles", builtin_cycles);
    symtab_get_def("Cycles")->attributes |= ATTR_NHOLDALL | ATTR_PROTECTED;
    symtab_set_docstring("Cycles",
        "Cycles[{{c11, c12, ...}, {c21, ...}, ...}]\n"
        "\trepresents a permutation in disjoint cycle form: c11 goes to c12, ..., the last back to c11.\n"
        "Evaluates to canonical form: each cycle starts at its smallest point, fixed points are dropped and\n"
        "cycles are ordered by their first point (Cycles[{{3, 1, 2}}] is Cycles[{{1, 2, 3}}]).");

    symtab_get_def("PermutationGroup")->attributes |= ATTR_PROTECTED;
    symtab_set_docstring("PermutationGroup",
        "PermutationGroup[{g1, g2, ...}]\n"
        "\trepresents the group generated by the permutations gi (each a Cycles).");

    symtab_add_builtin("PermutationList", builtin_permutationlist);
    symtab_get_def("PermutationList")->attributes |= ATTR_PROTECTED;
    symtab_set_docstring("PermutationList",
        "PermutationList[perm]\n"
        "\tgives the image list {perm(1), ..., perm(m)} of the Cycles perm, up to its largest moved point.\n"
        "PermutationList[perm, n]\n"
        "\tgives the list of length n.");

    symtab_add_builtin("PermutationCycles", builtin_permutationcycles);
    symtab_get_def("PermutationCycles")->attributes |= ATTR_PROTECTED;
    symtab_set_docstring("PermutationCycles",
        "PermutationCycles[list]\n"
        "\tgives the canonical Cycles of the permutation list list.");

    symtab_add_builtin("GroupElements", builtin_groupelements);
    symtab_get_def("GroupElements")->attributes |= ATTR_PROTECTED;
    symtab_set_docstring("GroupElements",
        "GroupElements[group]\n"
        "\tgives every element of the permutation group, as Cycles, ordered by image list.\n"
        "GroupElements[group, {k1, k2, ...}]\n"
        "\tgives the elements at positions ki of that list (negative positions count from the end).");

    symtab_add_builtin("GroupOrder", builtin_grouporder);
    symtab_get_def("GroupOrder")->attributes |= ATTR_PROTECTED;
    symtab_set_docstring("GroupOrder",
        "GroupOrder[group]\n"
        "\tgives the number of elements of the permutation group.");
}
